def gen(rng):
    def fmt(A, edges):
        return f'{len(A)} {len(edges)}\n' + ' '.join(map(str, A)) + ('\n' if edges else '\n') + '\n'.join(f'{u} {v} {w}' for u, v, w in edges)

    def rand_case(n, m, amax, wmax, connected):
        edges = []
        if connected:
            for v in range(2, n + 1):
                edges.append((rng.randint(1, v - 1), v, rng.randint(1, wmax)))
        while len(edges) < m:
            u, v = rng.randint(1, n), rng.randint(1, n)
            if u != v:
                edges.append((u, v, rng.randint(1, wmax)))
        rng.shuffle(edges)
        edges = [(u, v, w) if rng.random() < 0.5 else (v, u, w) for u, v, w in edges]
        return fmt([rng.randint(1, amax) for _ in range(n)], edges)

    tests = [
        fmt([10, 1, 5], [(1, 2, 2), (2, 3, 1)]),
        fmt([7, 3, 9, 4], [(1, 2, 1)]),
        fmt([5], []),
        fmt([1, 1], [(1, 2, 1)]),
        fmt([10**9, 1], [(1, 2, 10**9)]),
        fmt([4, 6, 8], [(1, 2, 1), (1, 2, 5), (2, 3, 1)]),
    ]
    for n in (2, 3, 4, 6, 8, 10, 12):
        for _ in range(3):
            m = rng.randint(0, 2 * n)
            tests.append(rand_case(n, m, rng.choice([5, 30, 1000]), rng.choice([3, 10, 100]), rng.random() < 0.5))
    N = 50000
    M = 60000
    tests.append(rand_case(N, M, 10**9, 10**9, True))
    tests.append(rand_case(N, M, 10**9, 1000, False))
    tests.append(rand_case(N, N - 1, 10**9, 10**4, True))
    # path graph with one cheap concert at the end
    A = [10**9] * N
    A[-1] = 1
    edges = [(i, i + 1, rng.randint(1, 1000)) for i in range(1, N)]
    tests.append(fmt(A, edges))
    tests.append(rand_case(N, M, 10**5, 10, True))
    return tests

